/*
 * A267006  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 84" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267006
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A267006:  rule‑84 cellular‑automaton initiated with a single
   ON cell; the sequence records the bits of successive rows read row‑by‑row. */

#include <stdint.h>
#include <stdlib.h>

/* Integer square root: floor(sqrt(n)) for non‑negative n. */
static idx_t int_sqrt(idx_t n)
{
    if (n == 0) return 0;
    idx_t lo = 0, hi = 1;
    /* Find an upper bound hi > sqrt(n) */
    while (hi <= n / hi)
        hi <<= 1;
    lo = hi >> 1;
    /* Binary search for floor(sqrt(n)) */
    while (lo <= hi)
    {
        idx_t mid = lo + ((hi - lo) >> 1);
        if (mid <= n / mid)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return hi;
}

/* Rule 84 lookup table: index = left*4 + centre*2 + right */
static const unsigned char rule84[8] = {
    0, /* 000 */
    0, /* 001 */
    1, /* 010 */
    0, /* 011 */
    1, /* 100 */
    0, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

seq_t a(idx_t n)
{
    /* Determine the row index r that contains position n.  Rows have
       lengths 1,3,5,…; cumulative length up to row r is (r+1)². */
    idx_t r = int_sqrt(n);

    /* Starting index of row r */
    idx_t start = r * r;
    /* Position within that row (0‑based) */
    idx_t pos = n - start;

    /* Allocate and initialise the first row (single ON cell) */
    unsigned char *prev = (unsigned char *)malloc(1);
    if (!prev) return (seq_t)0;   /* allocation failure – unlikely */
    prev[0] = 1;
    idx_t prev_width = 1;          /* current row width */

    /* Generate successive rows until we reach row r */
    for (idx_t row = 1; row <= r; ++row)
    {
        idx_t new_width = prev_width + 2;
        unsigned char *curr = (unsigned char *)malloc(new_width);
        if (!curr) { free(prev); return (seq_t)0; }

        for (idx_t j = 0; j < new_width; ++j)
        {
            unsigned char left   = (j >= 2)         ? prev[j - 2] : 0;
            unsigned char centre = (j >= 1 && j - 1 < prev_width) ? prev[j - 1] : 0;
            unsigned char right  = (j < prev_width) ? prev[j] : 0;
            unsigned char pattern = (left << 2) | (centre << 1) | right;
            curr[j] = rule84[pattern];
        }

        free(prev);
        prev = curr;
        prev_width = new_width;
    }

    seq_t result = (seq_t)prev[pos];
    free(prev);
    return result;
}
